#!/bin/sh
# Generated by `re-check lab --write` from book.toml, the chapters' steps and examples/stack.toml. Don't edit by hand.
# Stops this book's lab: the cluster is deleted, and your files stay in the workspace.
set -eu
book_dir=$(cd "$(dirname "$0")/.." && pwd)
slug=k3s-sampler
stack=k3s
lab_home="${RE_LAB_HOME:-$HOME/.rolling-edition/$slug}"
work="$lab_home/work"
bin="$lab_home/bin"

say() { printf '%s\n' "$*"; }
fail() { printf '%s\n' "$*" >&2; exit 1; }

cluster=re-k3s-sampler
[ -x "$bin/k3d" ] && "$bin/k3d" cluster delete "$cluster" >/dev/null 2>&1 || true
rm -f "$lab_home/kubeconfig"
say "Stopped: the cluster is deleted."
say "Your files stay in $work; lab/chapter.sh starts any chapter fresh."
